CREATE TABLE IF NOT EXISTS admins (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(32) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (id INT AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(150) NOT NULL UNIQUE, name_en VARCHAR(200) NOT NULL, name_si VARCHAR(200) NOT NULL, category VARCHAR(30) NOT NULL, description_en TEXT NOT NULL, description_si TEXT NOT NULL, image VARCHAR(350) NOT NULL, featured TINYINT NOT NULL DEFAULT 0, active TINYINT NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS quotations (id INT AUTO_INCREMENT PRIMARY KEY, reference VARCHAR(40) NOT NULL UNIQUE, customer_name VARCHAR(100) NOT NULL, phone VARCHAR(30) NOT NULL, email VARCHAR(150), company VARCHAR(150), product VARCHAR(140) NOT NULL, material VARCHAR(40), quantity VARCHAR(50) NOT NULL, dimensions VARCHAR(120), printing VARCHAR(30), delivery_location VARCHAR(160), notes TEXT, attachment_name VARCHAR(100), attachment_original VARCHAR(180), status VARCHAR(20) NOT NULL DEFAULT 'new', created_at DATETIME NOT NULL, INDEX quotes_created (created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings (key_name VARCHAR(80) PRIMARY KEY, value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
